const payload = $json.body ?? $json;

if (!payload || typeof payload !== 'object') {
  throw new Error('Expected a JSON object from Restock Watch');
}
if (typeof payload.title !== 'string' || typeof payload.body !== 'string') {
  throw new Error('Payload must contain title and body strings');
}
if (!Array.isArray(payload.changes)) {
  throw new Error('Payload must contain a changes array');
}

return [{
  json: {
    title: payload.title,
    body: payload.body,
    changes: payload.changes,
    actionable: Boolean(payload.actionable),
    receivedAt: new Date().toISOString()
  }
}];
